package greet

import "testing"

func TestGreetName(t *testing.T) {
	if got := Greet("Ada"); got != "Hello, Ada!" {
		t.Fatalf("Greet(Ada) = %q", got)
	}
}

// TestGreetEmpty covers GRT-002.
func TestGreetEmpty(t *testing.T) {
	if got := Greet(""); got != "Hello, stranger!" {
		t.Fatalf("Greet(\"\") = %q", got)
	}
}
